class Bread:
    def __init__(self, flavor, price):
        self.flavor = flavor
        self.price = price

    def discount(self, won):
        self.price = self.price - won

    def total(self, qty):
        return self.price * qty

a = Bread("팥", 1000)
b = Bread("슈크림", 1200)
a.discount(200)
print(a.price, b.price)
print(a.total(3))

